#!/usr/bin/env python3
"""Longevity trial tracking and discovery extraction."""

from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass, field
from statistics import mean
from typing import Any, Dict, List


@dataclass
class TrialMetadata:
    """Trial-level metadata and timeline fields."""

    trial_id: str
    sponsor: str
    phase: str
    status: str
    start_date: str
    expected_end_date: str


@dataclass
class ParticipantCohort:
    """Cohort-level trial analysis container."""

    phase_number: int
    total_participants: int
    outcomes: List[Dict[str, Any]] = field(default_factory=list)

    def add_participant_outcome(
        self, participant_id: str, treatment_arm: str, age_reversal: float
    ) -> None:
        self.outcomes.append(
            {
                "participant_id": participant_id,
                "treatment_arm": treatment_arm,
                "age_reversal": float(age_reversal),
            }
        )

    def calculate_mean_age_reversal(self) -> float:
        if not self.outcomes:
            return 0.0
        return round(mean(row["age_reversal"] for row in self.outcomes), 3)

    def identify_responders(self, threshold_years: float = 5.0) -> List[str]:
        return [
            row["participant_id"]
            for row in self.outcomes
            if row.get("age_reversal", 0.0) >= threshold_years
        ]

    def compare_treatment_arms(self) -> Dict[str, float]:
        grouped: defaultdict[str, List[float]] = defaultdict(list)
        for row in self.outcomes:
            grouped[row["treatment_arm"]].append(row["age_reversal"])
        return {arm: round(mean(values), 3) for arm, values in grouped.items() if values}


class EfficacyAnalyzer:
    """Predicts trial efficacy and success probabilities."""

    def __init__(self, cohort: ParticipantCohort) -> None:
        self.cohort = cohort

    def estimate_success_probability(self, efficacy_threshold: float = 3.0) -> float:
        outcomes = self.cohort.outcomes
        if not outcomes:
            return 0.0
        responders = [row for row in outcomes if row["age_reversal"] >= efficacy_threshold]
        return round(len(responders) / len(outcomes), 3)


class SafetyMonitor:
    """Tracks and summarizes adverse events by treatment arm."""

    def __init__(self) -> None:
        self._events: List[Dict[str, Any]] = []

    def log_adverse_event(
        self, participant_id: str, treatment_arm: str, severity: str, description: str
    ) -> None:
        self._events.append(
            {
                "participant_id": participant_id,
                "treatment_arm": treatment_arm,
                "severity": severity,
                "description": description,
            }
        )

    def calculate_safety_score(self) -> float:
        if not self._events:
            return 1.0
        severity_weights = {"mild": 0.1, "moderate": 0.3, "severe": 0.6}
        penalty = sum(severity_weights.get(event["severity"], 0.2) for event in self._events)
        return round(max(0.0, 1.0 - penalty / max(len(self._events), 1)), 3)

#!/usr/bin/env python3
"""

Groups harvested research by normalized titles and tracks source diversity.
Corroboration is metadata-level evidence only and never establishes a
mathematical theorem or proof.
"""

from __future__ import annotations
import json
import re
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / "data" / "research" / "riemann_hypothesis_harvest.json"


def utcnow():
    return datetime.now(timezone.utc).isoformat()


def normalize_title(title):
    return re.sub(r"[^a-z0-9]+", " ", (title or "").lower()).strip()


def main():
    data = json.loads(SOURCE.read_text(encoding="utf-8"))
    records = data.get("records", [])

    groups = {}
    for record in records:
        key = normalize_title(record.get("title", ""))
        if key:
            groups.setdefault(key, []).append(record)

    for key, matches in groups.items():
        sources = sorted({r.get("source", "") for r in matches if r.get("source")})
        for record in matches:
            record["corroboration"] = {
                "checked_at": utcnow(),
                "matching_metadata_records": len(matches),
                "distinct_sources": sources,
                "source_count": len(sources),
                "status": (
                    "metadata_corroborated" if len(sources) > 1 else "single_source_metadata"
                ),
                "mathematical_verification": False,
                "rule": (
                    "Metadata corroboration does not establish the truth "
                    "or validity of a mathematical claim."
                ),
            }

    data["corroboration_policy"] = {
        "level": "metadata_only",
        "mathematical_verification": False,
        "rule": (
            "Independent expert mathematical verification is required "
            "before any claim may be represented as established."
        ),
        "last_checked_at": utcnow(),
    }

    SOURCE.write_text(
        json.dumps(data, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )

    print(f"Corroboration checked for {len(records)} records.")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""

Assigns metadata-quality signals without determining mathematical truth.
No score can upgrade a claim to an established mathematical result.
"""

from __future__ import annotations
import json
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / "data" / "research" / "riemann_hypothesis_harvest.json"


def utcnow():
    return datetime.now(timezone.utc).isoformat()


def quality_score(record):
    score = 0
    if record.get("title"):
        score += 20
    if record.get("authors"):
        score += 20
    if record.get("published"):
        score += 15
    if record.get("url"):
        score += 20
    if record.get("summary"):
        score += 15
    if record.get("source"):
        score += 10
    return score


def main():
    data = json.loads(SOURCE.read_text(encoding="utf-8"))
    records = data.get("records", [])

    for record in records:
        score = quality_score(record)
        record["quality_gate"] = {
            "checked_at": utcnow(),
            "metadata_quality_score": score,
            "status": "metadata_complete" if score >= 80 else "metadata_partial",
            "mathematical_truth_assessment": False,
            "rule": (
                "Metadata quality measures record completeness only and "
                "does not assess whether a mathematical claim is correct."
            ),
        }

    data["quality_gate_policy"] = {
        "purpose": "metadata_quality_only",
        "mathematical_verification": False,
        "records_checked": len(records),
        "checked_at": utcnow(),
    }

    SOURCE.write_text(
        json.dumps(data, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )
    print(f"Quality gate checked {len(records)} records.")


if __name__ == "__main__":
    main()

