        self,
        path: Path = QUEUE_PATH,
    ) -> None:
        self.path = path
        self.path.parent.mkdir(
            parents=True,
            exist_ok=True,
        )

    def load(self) -> list[Capability]:
        if not self.path.exists():
            return []

        raw = json.loads(
            self.path.read_text(
                encoding="utf-8",
            )
        )

        return [
            Capability(**item)
            for item in raw
        ]

    def save(
        self,
        capabilities: list[Capability],
    ) -> None:
        payload = [
            asdict(item)
            for item in capabilities
        ]

        self.path.write_text(
            json.dumps(
                payload,
                indent=2,
                ensure_ascii=False,
            )
            + "\n",
            encoding="utf-8",
        )

    def add(
        self,
        capability: Capability,
    ) -> None:
        items = self.load()

        if any(
            item.id == capability.id
            for item in items
        ):
            return

