)


@dataclass
class ChangeImpactReport:
    targets: list[str]
    impacts: list[RepositoryImpact]
    highest_risk: str
    total_dependents: int
    related_tests: list[str]

    def to_dict(self) -> dict:
        return {
            "targets": self.targets,
            "impacts": [impact.to_dict() for impact in self.impacts],
            "highest_risk": self.highest_risk,
            "total_dependents": self.total_dependents,
            "related_tests": self.related_tests,
        }


_RISK_ORDER = {
    "low": 0,
    "medium": 1,
    "high": 2,
}


class ChangeImpactAnalyzer:
    """Analyze repository consequences before autonomous code changes."""

    def __init__(self, root: str | Path):
        self.root = Path(root).resolve()
        self.causality = RepositoryCausality(self.root)

    def analyze(
        self,
        targets: Iterable[str | Path],
    ) -> ChangeImpactReport:
        normalized = list(targets)
        impacts = self.causality.analyze_many(normalized)

        highest_risk = "low"

        for impact in impacts:
            if _RISK_ORDER[impact.risk_level] > _RISK_ORDER[highest_risk]:
                highest_risk = impact.risk_level

        related_tests = sorted(
            {
                test
                for impact in impacts
                for test in impact.related_tests
            }
        )

        total_dependents = sum(
            len(impact.dependents)
            for impact in impacts
        )

        return ChangeImpactReport(
            targets=[str(Path(target)) for target in normalized],
            impacts=impacts,
            highest_risk=highest_risk,
            total_dependents=total_dependents,
            related_tests=related_tests,
        )

