from dataclasses import dataclass
from typing import Optional

from .feedback_store import FeedbackStore


@dataclass
class RiskPolicy:
    max_risk: float = 0.70
    minimum_samples: int = 25
    lower_bound: float = 0.40
    upper_bound: float = 0.90


class AdaptiveRiskPolicy:
    def __init__(
        self,
        store: Optional[FeedbackStore] = None,
        policy: Optional[RiskPolicy] = None,
    ) -> None:
        self.store = store or FeedbackStore()
        self.policy = policy or RiskPolicy()

    def recommended_threshold(self) -> float:
        runs = self.store.recent_runs(
            limit=max(self.policy.minimum_samples * 4, 100)
        )

        if len(runs) < self.policy.minimum_samples:
            return self.policy.max_risk

        passed_risks = [
            float(run["risk_score"])
            for run in runs
            if run["validation_pass"]
        ]

        failed_risks = [
            float(run["risk_score"])
            for run in runs
            if not run["validation_pass"]
        ]

        if not failed_risks:
            return self.policy.max_risk

        first_failure = min(failed_risks)

        if passed_risks:
            successful_max = max(passed_risks)
            candidate = min(
                first_failure,
                successful_max + 0.05,
            )
        else:
            candidate = first_failure - 0.05

        return max(
            self.policy.lower_bound,
            min(
                self.policy.upper_bound,
                candidate,
            ),
        )

    def evaluate(self, risk_score: float) -> dict:
        threshold = self.recommended_threshold()

        return {
            "risk_score": risk_score,
            "threshold": threshold,
            "approved": risk_score <= threshold,
            "adaptive": (
                len(
                    self.store.recent_runs(
                        self.policy.minimum_samples
                    )
                )
                >= self.policy.minimum_samples
            ),
        }

    def update_policy(self) -> dict:
        old_value = self.policy.max_risk
        new_value = self.recommended_threshold()

        if new_value != old_value:
            self.store.record_policy_update(
                metric="max_risk",
                old_value=old_value,
                new_value=new_value,
                reason=(
                    "Adjusted from accumulated "
                    "validation outcomes."
                ),
            )
            self.policy.max_risk = new_value

"""
Barrot Claim Lifecycle Engine.

Claims remain revisable. Status reflects available evidence rather than
permanently declaring a claim true or false.
"""

from __future__ import annotations

from typing import Any


class ClaimLifecycleEngine:
    """Determine a claim's current evidence-based lifecycle state."""

    def determine(
        self,
        supporting_sources: int,
        conflicting_sources: int,
        confidence: float,
    ) -> dict[str, Any]:
        if conflicting_sources > 0 and supporting_sources > 0:
            status = "disputed"
        elif conflicting_sources > 0:
            status = "challenged"
        elif supporting_sources >= 2:
            status = "supported"
        elif supporting_sources >= 1:
            status = "candidate"
        else:
            status = "unverified"

        return {
            "status": status,
            "supporting_sources": supporting_sources,
            "conflicting_sources": conflicting_sources,
            "confidence": round(confidence, 3),
        }

