def run(cmd, check=True, quiet=False):
    print("+", cmd)
    r = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    if not quiet:
        if r.stdout.strip():
            print(r.stdout[:3000])
        if r.stderr.strip():
            print(r.stderr[:3000])
    if check and r.returncode != 0:
        sys.exit(f"command failed: {cmd}\n{r.stderr[:1000]}")
    return r.stdout


