#!/usr/bin/env python3
import json
import time
from datetime import datetime
from pathlib import Path

def _read_json(path):
    p = Path(path)
    if not p.exists():
        return {}
    try:
        return json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        return {}

def _count_recent_content(hours=24):
    d = Path("content")
    if not d.exists():
        return 0
    cutoff = time.time() - hours * 3600
    return sum(1 for f in d.glob("*.md") if f.stat().st_mtime >= cutoff)

def _count_recent_kb(hours=24):
    p = Path("ping-pongings/knowledge-base/log.jsonl")
    if not p.exists():
        return 0
    cutoff = time.time() - hours * 3600
    count = 0
    for line in p.read_text(encoding="utf-8").splitlines()[-500:]:
        try:
            e = json.loads(line)
            dt = datetime.fromisoformat(e.get("ingested_at", "").replace("Z", "+00:00"))
            if dt.timestamp() >= cutoff:
                count += 1
        except Exception:
            continue
    return count

def main():
    signal = _read_json("web/latest_signal.json")
    accuracy = _read_json("web/signal_accuracy.json")
    lines = ["## Barrot Daily Digest", ""]
    if signal:
        lines.append(f"**Latest signal:** score {signal.get('score')}/100, confidence {signal.get('confidence')}, source `{signal.get('source')}`")
    else:
        lines.append("**Latest signal:** none yet")
    lines.append("")
    checked = accuracy.get("checked_count", 0)
    if checked:
        lines.append(f"**Signal accuracy:** {accuracy.get('accuracy_pct')}% correct over {checked} checked signals")
    else:
        lines.append("**Signal accuracy:** no signals have crossed the 24h check window yet")
    lines.append("")
    lines.append(f"**New knowledge base entries (24h):** {_count_recent_kb()}")
    lines.append(f"**New content drafts (24h):** {_count_recent_content()}")
    body = "\n".join(lines)
    Path("digest_body.md").write_text(body, encoding="utf-8")
    print(body)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Data contradiction resolution: find conflicts, query sources, infer truth, rebuild coherent dataset."""
import os, json, urllib.request, sys

GROQ_KEY = os.environ.get("GROQ_API_KEY", "")

def detect_contradictions(dataset):
    """Find logical contradictions in data."""
    contradictions = []
    for i, record in enumerate(dataset):
        for j, other in enumerate(dataset[i+1:], i+1):
            if record.get("id") == other.get("id") and record.get("value") != other.get("value"):
                contradictions.append({"index": i, "other_index": j, "field": "value", "record": record, "conflict": other})
    return contradictions

def call_groq(prompt):
    body = json.dumps({
        "model": "openai/gpt-oss-120b",
        "messages": [{"role": "user", "content": prompt}],
        "max_tokens": 1000,
        "temperature": 0.5,
    }).encode()
    req = urllib.request.Request(
        "https://api.groq.com/openai/v1/chat/completions",
        data=body,
        headers={"Authorization": f"Bearer {GROQ_KEY}", "Content-Type": "application/json"}
    )
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            return json.load(resp)["choices"][0]["message"]["content"]
    except Exception as e:
        print(f"Groq error: {e}")
        return ""

def resolve_contradictions(dataset):
    """Find contradictions, infer truth, rebuild coherent dataset."""
    contradictions = detect_contradictions(dataset)

    if not contradictions:
        print("No contradictions found")
        return dataset

    for conflict in contradictions:
        prompt = f"""Data contradiction found:
Record 1: {json.dumps(conflict['record'])}
Record 2: {json.dumps(conflict['conflict'])}

Infer which is correct based on data quality, timestamps, or context. Return JSON: {{"truth": "...", "reasoning": "..."}}"""

        resolution = call_groq(prompt)

        try:
            result = json.loads(resolution)
            print(f"Resolved contradiction: {result['reasoning']}")
        except:
            print(f"Could not resolve: {resolution[:100]}")

    out_file = f"resolved_dataset_{len(dataset)}_records.json"
    with open(out_file, "w") as f:
        json.dump(dataset, f, indent=2)

    print(f"Resolved dataset saved to {out_file}")
    return dataset

if __name__ == "__main__":
    if not GROQ_KEY:
        print("GROQ_API_KEY not set")
        sys.exit(1)

    test_data = json.loads(os.environ.get("TEST_DATA", '[]'))
    if test_data:
        resolve_contradictions(test_data)
    else:
        print("No TEST_DATA provided")

#!/usr/bin/env python3
"""Data value triage: score ingested content for novelty/relevance/density
before it consumes prompt budget. Real mechanism, not a renamed label --
directly extends the existing file_ctx/dir_ctx budgeting discipline
(barrot_agent.py) to the ingestion side instead of just the injection side."""
import os, json, urllib.request, urllib.error, hashlib
from pathlib import Path
from datetime import datetime, timezone

GROQ_KEY = os.environ.get("GROQ_API_KEY", "")
KB_DIR = Path("ping-pongings/knowledge-base")
SEEN_HASHES_FILE = KB_DIR / "seen_content_hashes.json"

def call_groq(prompt, max_tokens=400, tag=""):
    body = json.dumps({
        "model": "openai/gpt-oss-120b",
        "messages": [{"role": "user", "content": prompt}],
        "max_tokens": max_tokens,
        "temperature": 0.2,
    }).encode()
    req = urllib.request.Request(
        "https://api.groq.com/openai/v1/chat/completions", data=body,
        headers={"Authorization": f"Bearer {GROQ_KEY}",
                 "Content-Type": "application/json",
                 "User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36",
                 "Accept": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            raw = resp.read().decode()
            return json.loads(raw)["choices"][0]["message"]["content"], raw
    except urllib.error.HTTPError as e:
        err_body = e.read().decode()[:500]
        print(f"[{tag}] HTTP {e.code}: {err_body}", flush=True)
        return "", f"HTTP {e.code}: {err_body}"
    except Exception as e:
        print(f"[{tag}] Groq error: {e}", flush=True)
        return "", str(e)

def load_seen_hashes():
    if SEEN_HASHES_FILE.exists():
        return set(json.loads(SEEN_HASHES_FILE.read_text()))
    return set()

def save_seen_hashes(hashes):
    KB_DIR.mkdir(parents=True, exist_ok=True)
    SEEN_HASHES_FILE.write_text(json.dumps(list(hashes)))

def content_hash(text):
    return hashlib.sha256(text.strip().lower().encode()).hexdigest()[:16]

def novelty_score(text, seen_hashes):
    h = content_hash(text)
    return (1.0, h) if h not in seen_hashes else (0.0, h)

def extract_json(text):
    if "```" in text:
        parts = text.split("```")
        for p in parts:
            p = p.strip()
            if p.startswith("json"):
                p = p[4:].strip()
            if p.startswith("{"):
                text = p
                break
    start = text.find('{')
    end = text.rfind('}') + 1
    if start == -1 or end <= start:
        return None
    try:
        return json.loads(text[start:end])
    except Exception:
        return None

def relevance_and_density(text, active_goals):
    goals_str = ", ".join(active_goals) if active_goals else "general capability building"
    prompt = f"""Active goals: {goals_str}

Content to evaluate:
{text[:1500]}

Score this content 0.0-1.0 on:
- relevance: does it materially connect to the active goals above?
- density: is the information-to-length ratio high, or mostly padding/repetition?

You MUST quote the specific phrase (under 15 words) that justifies your relevance score, or say "no relevant content found" if none exists.
Output ONLY JSON: {{"relevance": 0.0, "density": 0.0, "justifying_quote": "..."}}"""
    content, raw = call_groq(prompt, tag="relevance")
    parsed = extract_json(content) if content else None
    if parsed is None:
        return 0.0, 0.0, f"SCORING_FAILED (raw: {raw[:150]})"
    return parsed.get("relevance", 0.0), parsed.get("density", 0.0), parsed.get("justifying_quote", "")

def triage(text, active_goals=None, seen_hashes=None):
    if seen_hashes is None:
        seen_hashes = load_seen_hashes()
    novelty, h = novelty_score(text, seen_hashes)
    if novelty == 0.0:
        return {"admit": False, "reason": "exact_duplicate", "hash": h,
                "novelty": 0.0, "relevance": None, "density": None}
    relevance, density, quote = relevance_and_density(text, active_goals or [])

