    "arxiv_cs_se": [
        "https://rss.arxiv.org/rss/cs.SE",
    ],
    "arxiv_cs_ai": [
        "https://rss.arxiv.org/rss/cs.AI",
    ],
    "benchmark_news": [
        "https://news.google.com/rss/search?q=%22SWE-bench%22+OR+%22coding+agent+benchmark%22+when:7d",
    ],
}


def fetch(url):
    req = urllib.request.Request(
        url,
        headers={
            "User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36"
        },
    )
    with urllib.request.urlopen(req, timeout=20) as r:
        return r.read()


def parse_rss(raw, source, feed_url, limit=10):
    out = []
    try:
        root = ET.fromstring(raw)
    except ET.ParseError:
        return out
    for item in root.iter("item"):
        title = (item.findtext("title") or "").strip()
        link = (item.findtext("link") or "").strip()
        desc = (item.findtext("description") or "").strip()
        pub = (item.findtext("pubDate") or "").strip()
        if not title or not link:
            continue
        out.append(
            {
                "ingested_at": datetime.now(timezone.utc).isoformat(),
                "source": source,
                "feed": feed_url,
                "title": title[:300],
                "url": link,
                "published": pub,
                "summary": desc[:800],
            }
        )
        if len(out) >= limit:
            break
    return out


def load_seen():
    seen = set()
    if os.path.exists(LOG_PATH):
        with open(LOG_PATH) as f:
            for line in f:
                try:
                    seen.add(json.loads(line)["url"])
                except Exception:
                    pass
    return seen


def main():
    os.makedirs(KB_DIR, exist_ok=True)
    seen = load_seen()
    new, per_source = [], {}
    for source, urls in FEEDS.items():
        for u in urls:
            try:
                raw = fetch(u)
            except Exception as e:
                print(f"fetch failed {u}: {e}")
                continue
            for e in parse_rss(raw, source, u):
                if e["url"] in seen:
                    continue
                seen.add(e["url"])
                new.append(e)

