@dataclass
class StoryFact:
    key: str
    value: Any
    source: str = "creative-development"
    locked: bool = False


class StoryBible:
    """
    Canonical creative facts for a production.

    Locked facts cannot be silently replaced. Changes must be explicit.
    """

    def __init__(self) -> None:
        self._facts: dict[str, StoryFact] = {}

    def set_fact(
        self,
        key: str,
        value: Any,
        source: str = "creative-development",
        locked: bool = False,
        override: bool = False,
    ) -> StoryFact:
        existing = self._facts.get(key)
        if existing and existing.locked and existing.value != value and not override:
            raise ValueError(
                f"Story fact '{key}' is locked and cannot be silently changed."
            )

        fact = StoryFact(
            key=key,
            value=value,
            source=source,
            locked=locked or (existing.locked if existing else False),
        )
        self._facts[key] = fact
        return fact

    def get_fact(self, key: str, default: Any = None) -> Any:
        fact = self._facts.get(key)
        return fact.value if fact else default

    def facts(self) -> dict[str, Any]:
        return {
            key: {
                "value": fact.value,
                "source": fact.source,
                "locked": fact.locked,
            }
            for key, fact in self._facts.items()
        }

    def contradictions(self, proposed: dict[str, Any]) -> list[dict[str, Any]]:
        conflicts = []
        for key, value in proposed.items():
            existing = self._facts.get(key)
            if existing and existing.value != value:
                conflicts.append(
                    {
                        "key": key,
                        "established": existing.value,
                        "proposed": value,
                        "locked": existing.locked,
                    }
                )
        return conflicts

"""
Barrot Claim Lifecycle Engine.

Claims remain revisable. Status reflects available evidence rather than
permanently declaring a claim true or false.
"""

from __future__ import annotations

from typing import Any


class ClaimLifecycleEngine:
    """Determine a claim's current evidence-based lifecycle state."""

    def determine(
        self,
        supporting_sources: int,
        conflicting_sources: int,
        confidence: float,
    ) -> dict[str, Any]:
        if conflicting_sources > 0 and supporting_sources > 0:
            status = "disputed"
        elif conflicting_sources > 0:
            status = "challenged"
        elif supporting_sources >= 2:
            status = "supported"
        elif supporting_sources >= 1:
            status = "candidate"
        else:
            status = "unverified"

        return {
            "status": status,
            "supporting_sources": supporting_sources,
            "conflicting_sources": conflicting_sources,
            "confidence": round(confidence, 3),
        }

"""
Barrot Confidence Calibration.

Records predictions and later outcomes so confidence can eventually be compared
against observed accuracy. This module does not fabricate outcomes.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[2]
DATA_DIR = ROOT / "data" / "evolution"
CALIBRATION_FILE = DATA_DIR / "confidence_calibration.json"


class ConfidenceCalibrationEngine:
    """Maintain an auditable history of confidence assessments."""

    def __init__(self) -> None:
        DATA_DIR.mkdir(parents=True, exist_ok=True)

    def load(self) -> list[dict[str, Any]]:
        if not CALIBRATION_FILE.exists():
            return []

        try:
            return json.loads(CALIBRATION_FILE.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError):
            return []

    def save(self, records: list[dict[str, Any]]) -> None:
        CALIBRATION_FILE.write_text(
            json.dumps(records, indent=2, ensure_ascii=False, default=str),
            encoding="utf-8",
        )

    def record(
        self,
        claim_id: str,
        confidence: float,
        status: str,
    ) -> dict[str, Any]:
        record = {
            "claim_id": claim_id,
            "confidence": round(float(confidence), 3),
            "status": status,
            "outcome": None,
        }

        records = self.load()
        records.append(record)
        self.save(records)
        return record

    def resolve(
        self,
        claim_id: str,
        outcome: bool,
    ) -> bool:
        records = self.load()

        for record in reversed(records):
            if record.get("claim_id") == claim_id and record.get("outcome") is None:
                record["outcome"] = bool(outcome)
                self.save(records)
                return True

        return False

    def summary(self) -> dict[str, Any]:
        records = self.load()
        resolved = [record for record in records if record.get("outcome") is not None]

        if not resolved:
            return {
                "records": len(records),
                "resolved": 0,
                "accuracy": None,
            }

        correct = sum(
            (record["confidence"] >= 0.5 and record["outcome"] is True)
            or (record["confidence"] < 0.5 and record["outcome"] is False)
            for record in resolved
        )

        return {
            "records": len(records),
            "resolved": len(resolved),
            "accuracy": round(correct / len(resolved), 3),
        }

"""
Barrot Evidence Quality Engine.

Scores evidence using transparent, auditable factors. A quality score is not
a declaration of truth; it estimates how suitable a record is for reasoning.
"""

from __future__ import annotations

from datetime import datetime, timezone
from typing import Any


class EvidenceQualityEngine:
    """Evaluate evidence quality without treating source reputation as truth."""

    def score(self, evidence: dict[str, Any]) -> dict[str, Any]:
        factors: dict[str, float] = {}

        # Provenance: identifiable source and URL make evidence auditable.
        source = str(evidence.get("source", "")).strip()
        source_url = str(evidence.get("source_url", "")).strip()
        factors["provenance"] = 1.0 if source and source_url else 0.7 if source else 0.3

        # Completeness: essential fields required for inspection.
        required = ("claim_id", "claim", "source")
        present = sum(bool(evidence.get(field)) for field in required)
        factors["completeness"] = present / len(required)

        # Recency: evidence without a timestamp is usable but less informative.
        retrieved_at = evidence.get("retrieved_at")
        factors["recency"] = self._recency_score(retrieved_at)

        score = (
            factors["provenance"] * 0.40
            + factors["completeness"] * 0.35
            + factors["recency"] * 0.25
        )

        return {
            "quality_score": round(score, 3),
            "factors": factors,
        }

    @staticmethod
    def _recency_score(value: Any) -> float:
        if not value:
            return 0.5

        try:
            timestamp = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
            if timestamp.tzinfo is None:
                timestamp = timestamp.replace(tzinfo=timezone.utc)

            age_days = max(
                0,
                (datetime.now(timezone.utc) - timestamp).days,
            )

            if age_days <= 30:
                return 1.0
            if age_days <= 180:
                return 0.8
            if age_days <= 365:
                return 0.6
            return 0.4
        except (TypeError, ValueError):
            return 0.5

"""
Barrot Shared Evidence Store.

Maintains normalized claims independently from the cognitive outcome ledger.
The store preserves provenance and deduplicates evidence by claim identity.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[2]
DATA_DIR = ROOT / "data" / "evolution"
STORE_FILE = DATA_DIR / "evidence_store.json"


class EvidenceStore:
    """Persistent, bounded-access store for normalized evidence."""

    def __init__(self) -> None:
        DATA_DIR.mkdir(parents=True, exist_ok=True)

    def load(self) -> list[dict[str, Any]]:
        if not STORE_FILE.exists():
            return []

        try:
            return json.loads(STORE_FILE.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError):
            return []

    def save(self, records: list[dict[str, Any]]) -> None:
        STORE_FILE.write_text(
            json.dumps(records, indent=2, ensure_ascii=False, default=str),
            encoding="utf-8",
        )

    def add(self, evidence: dict[str, Any]) -> dict[str, Any]:
        """Store evidence unless an identical claim/source record exists."""
        claim_id = evidence.get("claim_id")
        if not claim_id:
            raise ValueError("Evidence requires a claim_id")

        records = self.load()

        # The same claim can be supported by multiple independent sources.
        duplicate = any(
            record.get("claim_id") == claim_id and record.get("source") == evidence.get("source")
            for record in records
        )

        if duplicate:
            return {"status": "duplicate", "claim_id": claim_id}

        records.append(evidence)
        self.save(records)

        return {"status": "stored", "claim_id": claim_id}

    def get(self, claim_id: str) -> list[dict[str, Any]]:
        """Return all evidence records associated with a claim."""
        return [record for record in self.load() if record.get("claim_id") == claim_id]

    def by_source(self, source: str) -> list[dict[str, Any]]:
