        api_key = os.getenv("COINBASE_API_KEY")
        api_secret = os.getenv("COINBASE_API_SECRET")

        self.client = (
            RESTClient(api_key=api_key, api_secret=api_secret)
            if api_key and api_secret
            else RESTClient()
