class DailyCapHit(Exception):
    pass


def ask_with_backoff(prompt):
    """Returns text, or raises DailyCapHit if Groq's error says per-day/token-quota."""
    attempts = 0
    while True:
        try:
            return ask(prompt)
        except urllib.error.HTTPError as e:
            body_txt = ""
